import{_ as a,a0 as m,w as p,s as l,I as s,x as t,a1 as n,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何在 Linux 上從 NetworkManager 切換為 systemd-network | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上從 NetworkManager 切換為 systemd-network | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上從 NetworkManager 切換為 systemd-network | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上從 NetworkManager 切換為 systemd-network | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20150831 How to switch from NetworkManager to systemd-networkd on Linux","title":"如何在 Linux 上從 NetworkManager 切換為 systemd-network","tag":"201511","desc":""},"relativePath":"201511/20150831 How to switch from NetworkManager to systemd-networkd on Linux.md","filePath":"[post].md"}'),i={name:"201511/20150831 How to switch from NetworkManager to systemd-networkd on Linux.md"};function w(k,e,y,u,g,f){const r=m("Link");return p(),l("div",null,[e[27]||(e[27]=s("h1",{id:"如何在-linux-上從-networkmanager-切換為-systemd-network",tabindex:"-1"},[t("如何在 Linux 上從 NetworkManager 切換為 systemd-network "),s("a",{class:"header-anchor",href:"#如何在-linux-上從-networkmanager-切換為-systemd-network","aria-label":"Permalink to “如何在 Linux 上從 NetworkManager 切換為 systemd-network”"},"​")],-1)),s("p",null,[e[1]||(e[1]=t("在 Linux 世界裏，對 ",-1)),n(r,{href:"http://xmodulo.com/use-systemd-system-administration-debian.html"},{default:o(()=>[...e[0]||(e[0]=[t("systemd",-1)])]),_:1}),e[2]||(e[2]=t(" 的採用一直是激烈爭論的主題，它的支持者和反對者之間的戰火仍然在燃燒。到了今天，大部分主流 Linux 發行版都已經採用了 systemd 作為默認的初始化（init）系統。",-1))]),e[28]||(e[28]=d("<p>正如其作者所説，作為一個 “從未完成、從未完善、但一直追隨技術進步” 的系統，systemd 已經不只是一個初始化進程，它被設計為一個更廣泛的系統以及服務管理平台，這個平台是一個包含了不斷增長的核心繫統進程、庫和工具的生態系統。</p><p><strong>systemd</strong> 的其中一部分是 <strong>systemd-networkd</strong>，它負責 systemd 生態中的網絡配置。使用 systemd-networkd，你可以為網絡設備配置基礎的 DHCP/靜態 IP 網絡。它還可以配置虛擬網絡功能，例如網橋、隧道和 VLAN。systemd-networkd 目前還不能直接支持無線網絡，但你可以使用 wpa_supplicant 服務配置無線適配器，然後把它和 <strong>systemd-networkd</strong> 聯繫起來。</p><p>在很多 Linux 發行版中，NetworkManager 仍然作為默認的網絡配置管理器。和 NetworkManager 相比，<strong>systemd-networkd</strong> 仍處於積極的開發狀態，還缺少一些功能。例如，它還不能像 NetworkManager 那樣能讓你的計算機在任何時候通過多種接口保持連接。它還沒有為更高層面的腳本編程提供 ifup/ifdown 鈎子函數。但是，systemd-networkd 和其它 systemd 組件（例如用於域名解析的 <strong>resolved</strong>、NTP 的<strong>timesyncd</strong>，用於命名的 udevd）結合的非常好。隨着時間增長，<strong>systemd-networkd</strong>只會在 systemd 環境中扮演越來越重要的角色。</p>",3)),s("p",null,[e[4]||(e[4]=t("如果你對 ",-1)),e[5]||(e[5]=s("strong",null,"systemd-networkd",-1)),e[6]||(e[6]=t(" 的進步感到高興，從 NetworkManager 切換到 systemd-networkd 是值得你考慮的一件事。如果你強烈反對 systemd，對 NetworkManager 或",-1)),n(r,{href:"http://xmodulo.com/disable-network-manager-linux.html"},{default:o(()=>[...e[3]||(e[3]=[t("基礎網絡服務",-1)])]),_:1}),e[7]||(e[7]=t("感到很滿意，那也很好。",-1))]),e[29]||(e[29]=d(`<p>但對於那些想嘗試 systemd-networkd 的人，可以繼續看下去，在這篇指南中學會在 Linux 中怎麼從 NetworkManager 切換到 systemd-networkd。</p><h3 id="需求" tabindex="-1">需求 <a class="header-anchor" href="#需求" aria-label="Permalink to “需求”">​</a></h3><p>systemd 210 及其更高版本提供了 systemd-networkd。因此諸如 Debian 8 &quot;Jessie&quot; (systemd 215)、 Fedora 21 (systemd 217)、 Ubuntu 15.04 (systemd 219) 或更高版本的 Linux 發行版和 systemd-networkd 兼容。</p><p>對於其它發行版，在開始下一步之前先檢查一下你的 systemd 版本。</p><pre><code>$ systemctl --version
</code></pre><h3 id="從-networkmanager-切換到-systemd-networkd" tabindex="-1">從 NetworkManager 切換到 Systemd-networkd <a class="header-anchor" href="#從-networkmanager-切換到-systemd-networkd" aria-label="Permalink to “從 NetworkManager 切換到 Systemd-networkd”">​</a></h3><p>從 NetworkManager 切換到 systemd-networkd 其實非常簡答（反過來也一樣）。</p><p>首先，按照下面這樣先停用 NetworkManager 服務，然後啓用 systemd-networkd。</p><pre><code>$ sudo systemctl disable NetworkManager
$ sudo systemctl enable systemd-networkd
</code></pre><p>你還要啓用 <strong>systemd-resolved</strong> 服務，systemd-networkd用它來進行域名解析。該服務還實現了一個緩存式 DNS 服務器。</p><pre><code>$ sudo systemctl enable systemd-resolved
$ sudo systemctl start systemd-resolved
</code></pre><p>當啓動後，<strong>systemd-resolved</strong> 就會在 /run/systemd 目錄下某個地方創建它自己的 resolv.conf。但是，把 DNS 解析信息存放在 /etc/resolv.conf 是更普遍的做法，很多應用程序也會依賴於 /etc/resolv.conf。因此為了兼容性，按照下面的方式創建一個到 /etc/resolv.conf 的符號鏈接。</p><pre><code>$ sudo rm /etc/resolv.conf
$ sudo ln -s /run/systemd/resolve/resolv.conf /etc/resolv.conf
</code></pre><h3 id="用-systemd-networkd-配置網絡連接" tabindex="-1">用 systemd-networkd 配置網絡連接 <a class="header-anchor" href="#用-systemd-networkd-配置網絡連接" aria-label="Permalink to “用 systemd-networkd 配置網絡連接”">​</a></h3><p>要用 systemd-networkd 配置網絡服務，你必須指定帶.network 擴展名的配置信息文本文件。這些網絡配置文件保存到 /etc/systemd/network 並從這裏加載。當有多個文件時，systemd-networkd 會按照字母順序一個個加載並處理。</p><p>首先創建 /etc/systemd/network 目錄。</p><pre><code>$ sudo mkdir /etc/systemd/network
</code></pre><h4 id="dhcp-網絡" tabindex="-1">DHCP 網絡 <a class="header-anchor" href="#dhcp-網絡" aria-label="Permalink to “DHCP 網絡”">​</a></h4><p>首先來配置 DHCP 網絡。對於此，先要創建下面的配置文件。文件名可以任意，但記住文件是按照字母順序處理的。</p><pre><code>$ sudo vi /etc/systemd/network/20-dhcp.network
</code></pre><hr><pre><code>[Match]
Name=enp3*

[Network]
DHCP=yes
</code></pre><p>正如你上面看到的，每個網絡配置文件包括了一個或多個 “sections”，每個 “section”都用 [XXX] 開頭。每個 section 包括了一個或多個鍵值對。<code>[Match]</code> 部分決定這個配置文件配置哪個（些）網絡設備。例如，這個文件匹配所有名稱以 ens3 開頭的網絡設備（例如 enp3s0、 enp3s1、 enp3s2 等等）對於匹配的接口，然後啓用 [Network] 部分指定的 DHCP 網絡配置。</p><h3 id="靜態-ip-網絡" tabindex="-1">靜態 IP 網絡 <a class="header-anchor" href="#靜態-ip-網絡" aria-label="Permalink to “靜態 IP 網絡”">​</a></h3><p>如果你想給網絡設備分配一個靜態 IP 地址，那就新建下面的配置文件。</p><pre><code>$ sudo vi /etc/systemd/network/10-static-enp3s0.network
</code></pre><hr><pre><code>[Match]
Name=enp3s0

[Network]
Address=192.168.10.50/24
Gateway=192.168.10.1
DNS=8.8.8.8
</code></pre><p>正如你猜測的， enp3s0 接口地址會被指定為 192.168.10.50/24，默認網關是 192.168.10.1， DNS 服務器是 8.8.8.8。這裏微妙的一點是，接口名 enp3s0 事實上也匹配了之前 DHCP 配置中定義的模式規則。但是，根據詞彙順序，文件 &quot;10-static-enp3s0.network&quot; 在 &quot;20-dhcp.network&quot; 之前被處理，對於 enp3s0 接口靜態配置比 DHCP 配置有更高的優先級。</p><p>一旦你完成了創建配置文件，重啓 systemd-networkd 服務或者重啓機器。</p><pre><code>$ sudo systemctl restart systemd-networkd
</code></pre><p>運行以下命令檢查服務狀態：</p><pre><code>$ systemctl status systemd-networkd
$ systemctl status systemd-resolved
</code></pre><p><img src="https://farm1.staticflickr.com/719/21010813392_76abe123ed_c.jpg" alt=""></p><h3 id="用-systemd-networkd-配置虛擬網絡設備" tabindex="-1">用 systemd-networkd 配置虛擬網絡設備 <a class="header-anchor" href="#用-systemd-networkd-配置虛擬網絡設備" aria-label="Permalink to “用 systemd-networkd 配置虛擬網絡設備”">​</a></h3><p><strong>systemd-networkd</strong> 同樣允許你配置虛擬網絡設備，例如網橋、VLAN、隧道、VXLAN、綁定等。你必須在用 .netdev 作為擴展名的文件中配置這些虛擬設備。</p><p>這裏我展示瞭如何配置一個橋接接口。</p><h4 id="linux-網橋" tabindex="-1">Linux 網橋 <a class="header-anchor" href="#linux-網橋" aria-label="Permalink to “Linux 網橋”">​</a></h4><p>如果你想創建一個 Linux 網橋(br0) 並把物理接口(eth1) 添加到網橋，你可以新建下面的配置。</p><pre><code>$ sudo vi /etc/systemd/network/bridge-br0.netdev
</code></pre><hr><pre><code>[NetDev]
Name=br0
Kind=bridge
</code></pre><p>然後按照下面這樣用 .network 文件配置網橋接口 br0 和從接口 eth1。</p><pre><code>$ sudo vi /etc/systemd/network/bridge-br0-slave.network
</code></pre><hr><pre><code>[Match]
Name=eth1

[Network]
Bridge=br0
</code></pre><hr><pre><code>$ sudo vi /etc/systemd/network/bridge-br0.network
</code></pre><hr><pre><code>[Match]
Name=br0

[Network]
Address=192.168.10.100/24
Gateway=192.168.10.1
DNS=8.8.8.8
</code></pre><p>最後，重啓 systemd-networkd。</p><pre><code>$ sudo systemctl restart systemd-networkd
</code></pre>`,52)),s("p",null,[e[9]||(e[9]=t("你可以用 ",-1)),n(r,{href:"http://xmodulo.com/how-to-configure-linux-bridge-interface.html"},{default:o(()=>[...e[8]||(e[8]=[t("brctl 工具",-1)])]),_:1}),e[10]||(e[10]=t(" 來驗證是否創建好了網橋 br0。",-1))]),e[30]||(e[30]=s("h3",{id:"總結",tabindex:"-1"},[t("總結 "),s("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),e[31]||(e[31]=s("p",null,"當 systemd 誓言成為 Linux 的系統管理器時，有類似 systemd-networkd 的東西來管理網絡配置也就不足為奇。但是在現階段，systemd-networkd 看起來更適合於網絡配置相對穩定的服務器環境。對於桌面/筆記本環境，它們有多種臨時有線/無線接口，NetworkManager 仍然是比較好的選擇。",-1)),s("p",null,[e[12]||(e[12]=t("對於想進一步瞭解 systemd-networkd 的人，可以參考官方",-1)),n(r,{href:"http://www.freedesktop.org/software/systemd/man/systemd.network.html"},{default:o(()=>[...e[11]||(e[11]=[t("man 手冊",-1)])]),_:1}),e[13]||(e[13]=t("瞭解完整的支持列表和關鍵點。",-1))]),e[32]||(e[32]=s("hr",null,null,-1)),s("p",null,[e[15]||(e[15]=t("via: ",-1)),n(r,{href:"http://xmodulo.com/switch-from-networkmanager-to-systemd-networkd.html"},{default:o(()=>[...e[14]||(e[14]=[t("http://xmodulo.com/switch-from-networkmanager-to-systemd-networkd.html",-1)])]),_:1})]),s("p",null,[e[19]||(e[19]=t("作者：",-1)),n(r,{href:"http://xmodulo.com/author/nanni"},{default:o(()=>[...e[16]||(e[16]=[t("Dan Nanni",-1)])]),_:1}),e[20]||(e[20]=t(" 譯者：",-1)),n(r,{href:"http://mutouxiaogui.cn/blog"},{default:o(()=>[...e[17]||(e[17]=[t("ictlyh",-1)])]),_:1}),e[21]||(e[21]=t(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:o(()=>[...e[18]||(e[18]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[24]||(e[24]=t("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[22]||(e[22]=[t("LCTT",-1)])]),_:1}),e[25]||(e[25]=t(" 原創編譯，",-1)),n(r,{href:"https://linux.cn/"},{default:o(()=>[...e[23]||(e[23]=[t("Linux中國",-1)])]),_:1}),e[26]||(e[26]=t(" 榮譽推出",-1))])])}const h=a(i,[["render",w]]);export{b as __pageData,h as default};
